const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  const sanJose = ee.Geometry.Point([-121.8863, 37.3382]);
  const region = sanJose.buffer(20000); // 20km buffer around San Jose

  // Time periods
  const juneDate = ['2020-06-01', '2020-06-30'];
  const augustDate = ['2020-08-20', '2020-08-31']; // Window around Aug 26

  // 2. Data Acquisition - Sentinel-2 for burn scar analysis
  function getS2Collection(dateRange, geometry) {
    return ee.ImageCollection('COPERNICUS/S2_SR_HARMONIZED')
      .filterBounds(geometry)
      .filterDate(dateRange[0], dateRange[1])
      .filter(ee.Filter.lt('CLOUDY_PIXEL_PERCENTAGE', 20));
  }

  function calculateNBR(img) {
    const nbr = img.normalizedDifference(['B8', 'B12']).rename('NBR');
    return img.addBands(nbr);
  }

  // Get collections
  const juneCol = getS2Collection(juneDate, region);
  const augustCol = getS2Collection(augustDate, region);

  // Check collection sizes
  const juneSize = juneCol.size().getInfo();
  const augustSize = augustCol.size().getInfo();

  console.log(`June 2020 Images: ${juneSize}`);
  console.log(`August 2020 Images: ${augustSize}`);

  if (juneSize === 0 || augustSize === 0) {
    console.log("<answer>C1</answer>");
    return;
  }

  // Get median composites
  const juneImg = calculateNBR(juneCol.median()).select('NBR');
  const augustImg = calculateNBR(augustCol.median()).select('NBR');

  // Calculate dNBR (pre-fire - post-fire)
  const dnbr = juneImg.subtract(augustImg).rename('dNBR');

  // Threshold for burn scars (dNBR > 0.1 indicates burning)
  const burnThreshold = 0.1;
  const juneBurned = juneImg.lt(-0.1); // Low NBR indicates burned
  const augustBurned = augustImg.lt(-0.1);
  const newBurns = dnbr.gt(burnThreshold); // Areas that became more burned

  // Count burned pixels
  const juneCount = juneBurned.reduceRegion({
    reducer: ee.Reducer.sum(),
    geometry: region,
    scale: 100,
    maxPixels: 1e9
  }).get('NBR').getInfo();

  const augustCount = augustBurned.reduceRegion({
    reducer: ee.Reducer.sum(),
    geometry: region,
    scale: 100,
    maxPixels: 1e9
  }).get('NBR').getInfo();

  const newBurnCount = newBurns.reduceRegion({
    reducer: ee.Reducer.sum(),
    geometry: region,
    scale: 100,
    maxPixels: 1e9
  }).get('dNBR').getInfo();

  console.log(`June burned pixels: ${Math.round(juneCount)}`);
  console.log(`August burned pixels: ${Math.round(augustCount)}`);
  console.log(`New burn pixels: ${Math.round(newBurnCount)}`);

  // Validation checks
  if (juneCount === null || augustCount === null || newBurnCount === null) {
    console.log("<answer>C3</answer>");
    return;
  }

  if (juneCount === 0 && augustCount === 0) {
    console.log("<answer>C2</answer>");
    return;
  }

  // Determine if burn scars expanded
  const burnExpanded = newBurnCount > 1000; // Threshold for meaningful expansion

  if (burnExpanded) {
    console.log("<answer>A</answer>");
  } else {
    console.log("<answer>B</answer>");
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
